mapper.select:
SELECT * FROM ( SELECT A.*, ROWNUM as rNum FROM (
SELECT q.qId, q.qName, q.qTitle, q.qContent, q.qHit, q.qDate, q.qGroup, q.qStep, q.qIndent, q.qSecret, q.qNotice, q.qParentName, m.userDept as qDept, m.userJob as qJob FROM qna_board q LEFT JOIN MEMBER m ON q.qName = m.userId
q.qTitle LIKE '%' || #{keyword} || '%' q.qContent LIKE '%' || #{keyword} || '%' q.qName LIKE '%' || #{keyword} || '%'
ORDER BY NVL(q.qNotice, 'N') DESC, q.qGroup DESC, q.qStep ASC
) A ) WHERE rNum BETWEEN #{start} AND #{end}

mapper.update:
UPDATE qna_board 
SET qTitle = #{qTitle}, qContent = #{qContent} 
WHERE qId = #{qId}

UPDATE qna_board 
SET qStep = qStep + 1
WHERE qGroup = #{qGroup} AND qStep > #{qStep}
